#!/usr/bin/env node
/**
 * Fails when a file exceeds the token limit (tokens ≈ non-CR bytes / 4,
 * default 5000, override with --max <tokens>). CR bytes are subtracted so
 * LF and CRLF checkouts measure identically.
 * Skips files not authored by agents: lockfiles, codegen output, migrations,
 * binary assets. Framework-agnostic: repo-specific generated files are
 * excluded via --exclude <regex>, never by editing the script.
 * Runs on plain Node.js — no dependencies. Linux, macOS, Windows.
 */

import { spawnSync } from 'node:child_process'
import { readFileSync, statSync } from 'node:fs'

const DEFAULT_MAX_TOKENS = 5000
const MAX_BYTES = DEFAULT_MAX_TOKENS * 4

/**
 * Universal skip-list of non-agent files. Framework-specific generated
 * files (e.g. payload-types.ts) belong in the caller's --exclude flags,
 * not here.
 */
const EXCLUDES = [
  // Lockfiles across ecosystems.
  /(?:^|\/)(?:bun\.lock|bun\.lockb|package-lock\.json|pnpm-lock\.yaml|yarn\.lock|Cargo\.lock|go\.sum|Gemfile\.lock|poetry\.lock|uv\.lock|pdm\.lock|composer\.lock)$/,
  /(?:^|\/)CHANGELOG\.md$/,
  /(?:^|\/)tsconfig\.tsbuildinfo$/,
  /\.map$/, // source maps
  /\.min\.(?:mjs|cjs|js|css)$/, // minified bundles
  /\.(?:gen|generated)\./, // codegen convention: schema.gen.ts, api.generated.ts, ...
]

/**
 * Path segments skipped everywhere (scans and direct args): vendored agent
 * tooling, migrations (generated by nearly every ORM/framework) and
 * __generated__ (Relay, GraphQL codegen).
 */
const SKIP_DIRS = new Set([
  '.agents',
  '.claude',
  '.codex',
  '.gemini',
  '.cursor',
  '.opencode',
  '.omo',
  '.bmad-loop',
  '_bmad',
  '_bmad-output',
  'migrations',
  '__generated__',
])

// SVG is text, but it is an image — agents must not edit its markup.
const BINARY =
  /\.(?:png|jpe?g|gif|webp|avif|ico|svg|woff2?|ttf|otf|eot|mp4|webm|mp3|wav|zip|gz|tar|wasm|pdf|db|sqlite)$/i

const userExcludes = []
const args = []
const raw = process.argv.slice(2)
let maxTokens = DEFAULT_MAX_TOKENS

for (let i = 0; i < raw.length; i++) {
  const arg = raw[i]

  if (arg === '--exclude') {
    addExclude(raw[++i] ?? '')
  } else if (arg.startsWith('--exclude=')) {
    addExclude(arg.slice(10))
  } else if (arg === '--max') {
    maxTokens = parseMax(raw[++i] ?? '')
  } else if (arg.startsWith('--max=')) {
    maxTokens = parseMax(arg.slice(6))
  } else {
    args.push(arg)
  }
}

function addExclude(source) {
  try {
    userExcludes.push(new RegExp(source))
  } catch {
    console.error(`Invalid --exclude regex: ${source}`)
    process.exit(2)
  }
}

function parseMax(source) {
  const value = Number(source)

  if (!Number.isInteger(value) || value < 1) {
    console.error(`Invalid --max value: ${source} (expected a positive integer)`)
    process.exit(2)
  }

  return value
}

/**
 * Windows hook args may carry backslashes; git always outputs forward
 * slashes. Normalize once, match everywhere.
 */
const toPosix = (p) => p.replaceAll('\\', '/')

function isSkipped(posixPath) {
  return (
    EXCLUDES.some((pattern) => pattern.test(posixPath)) ||
    BINARY.test(posixPath) ||
    posixPath.split('/').some((segment) => SKIP_DIRS.has(segment)) ||
    userExcludes.some((pattern) => pattern.test(posixPath))
  )
}

/**
 * Lists files git considers part of the repo (tracked + untracked), respecting
 * .gitignore, .git/info/exclude and the global excludesfile — the dynamic
 * replacement for a hardcoded build-artifact skip-list.
 *
 * @param {string} dir - Directory to list files from.
 * @returns {string[]} - List of file paths relative to the repo root.
 */
function gitListFiles(dir) {
  const proc = spawnSync(
    'git',
    ['ls-files', '--cached', '--others', '--exclude-standard', '--', dir],
    {
      encoding: 'utf8',
    },
  )

  if (proc.status !== 0) {
    console.error((proc.stderr || 'git ls-files failed').trim())
    process.exit(2)
  }

  return (proc.stdout || '').split('\n').filter(Boolean)
}

/**
 * Collects all files from a list of entries, skipping anything isSkipped
 * rejects. Applies to direct file args and directory scans alike.
 *
 * @param {string[]} entries - List of file or directory paths.
 * @returns {string[]} - List of file paths relative to the repo root.
 */
function collectFiles(entries) {
  const files = new Set()

  for (const entry of entries) {
    const path = toPosix(entry)

    if (isSkipped(path)) continue

    try {
      if (statSync(entry).isDirectory()) {
        for (const listed of gitListFiles(entry)) {
          const posix = toPosix(listed)
          if (!isSkipped(posix)) files.add(posix)
        }

        continue
      }
    } catch {
      continue
    }

    files.add(path)
  }

  return [...files]
}

if (args.includes('-h') || args.includes('--help')) {
  console.log(`check-token-limit — enforce a maximum token count per file.

WHAT IT DOES
  Reads each file passed as an argument and estimates its size in LLM
  tokens using tokens = ceil((bytes - CR) / 4). CR bytes are subtracted
  so LF and CRLF checkouts measure identically. Fails (exit 1) when any
  file exceeds the limit — ${DEFAULT_MAX_TOKENS} tokens (${MAX_BYTES} bytes) by default,
  override with --max — printing the offenders and instructions on how
  to split them.

WHY
  Large files are hard for AI coding agents to read, edit, and review
  within context limits. This hook keeps every committed file
  agent-friendly.

USAGE
  node check-token-limit.mjs <file|directory>... [options]

  Directories are scanned recursively (e.g. "." scans the whole repo).
  Directory scans list files via "git ls-files --exclude-standard", so they
  automatically respect .gitignore, .git/info/exclude and the global git
  excludes — gitignored build output is never scanned.

  Options:
    -h, --help         Show this help and exit.
    --exclude <regex>  Skip paths matching regex (repeatable). Use for
                       repo-specific generated files, e.g.
                       --exclude "payload-types\\.ts$".
    --max <tokens>     Override the default limit for this run, e.g.
                       --max=8000. Changing the committed default limit is
                       the user's decision, not the agent's.

  Skipped everywhere (not agent-authored):
    - Lockfiles: bun.lock(.b), package-lock.json, pnpm-lock.yaml, yarn.lock,
      Cargo.lock, go.sum, Gemfile.lock, poetry.lock, uv.lock, pdm.lock,
      composer.lock
    - Codegen conventions: *.gen.*, *.generated.*, __generated__/, migrations/
    - Source maps (*.map), minified (*.min.js/.css), CHANGELOG.md,
      tsconfig.tsbuildinfo
    - Binary assets, incl. SVG (images are never agent-edited)
    - Vendored agent tooling dirs (.agents, .claude, _bmad, ...)

  Exit codes:
    0  all files within the limit (or none passed)
    1  at least one file exceeds the limit
    2  git ls-files failed, invalid --exclude regex, or invalid --max value`)

  process.exit(0)
}

/** @type {Array<[string, number]>} */
const offenders = []

for (const file of collectFiles(args)) {
  let buf

  try {
    buf = readFileSync(file)
  } catch {
    continue
  }

  // Subtract CR bytes so CRLF and LF checkouts of the same file get the
  // same token count regardless of git's autocrlf setting.
  let cr = 0

  for (const byte of buf) {
    if (byte === 13) cr++
  }

  const tokens = Math.ceil((buf.length - cr) / 4)

  if (tokens > maxTokens) {
    offenders.push([file, tokens])
  }
}

if (offenders.length === 0) {
  process.exit(0)
}

const list = offenders
  .map(([file, tokens]) => `  - ${file} — ${tokens} tokens (limit: ${maxTokens})`)
  .join('\n')

console.error(`❌ Files exceed the ${maxTokens}-token limit (tokens ≈ (bytes - CR) / 4):
${list}

Split them before committing:

  Code (src/**):
  1. Extract related types & interfaces into "types.ts" next to the module.
  2. Extract constants and configuration into "constants.ts".
  3. Move independent helpers into their own module and import them.
  4. One React component per file; extract sub-components into siblings.
  5. Re-export the public API from "index.ts" so existing imports stay stable.

  Docs / Markdown:
  1. One topic per file; move deep sections into their own file and link to it.
  2. Move long code samples into "examples/" and reference the path.

  Data / fixtures:
  1. Trim to the minimum needed for the test.
  2. Move bulk data into a generator script instead of committing it.

Each file must stay under ${maxTokens} tokens (${maxTokens * 4} bytes).
If a file genuinely cannot be split, ask the user before raising the limit
via --max or adding an --exclude.
Run "git add" on the new files so they are included in this commit.`)

process.exit(1)
